const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const paths={menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',back:'m14 6-6 6 6 6',chevron:'m9 6 6 6-6 6',plus:'M12 5v14M5 12h14',send:'m5 12 14-7-5 14-3-6-6-1Zm6 1 8-8',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 14 7-5 12-10 8-14Z',more:'M5 12h.01M12 12h.01M19 12h.01',image:'M4 4h16v16H4ZM4 16l5-5 4 4 3-3 4 4M15 8h.01',file:'M6 3h8l4 4v14H6ZM14 3v5h4M9 12h6M9 16h6',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',phone:'M7 3H4c-3 9 8 20 17 17v-4l-5-2-2 3-7-7 3-2-3-5Z',video:'M3 6h12v12H3ZM15 10l6-3v10l-6-3',camera:'M3 7h4l2-3h6l2 3h4v13H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',smile:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM8 9h.01M16 9h.01M8 15q4 4 8 0',reply:'m9 5-6 6 6 6M3 11h10q7 0 7 8',copy:'M8 8h12v13H8ZM5 16H3V3h12v2',edit:'m4 16 12-12 4 4L8 20H4v-4ZM13 7l4 4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3ZM8 12l3 3 5-6',device:'M6 2h12v20H6ZM10 18h4',cloud:'M6 18a5 5 0 1 1 0-10 6 6 0 0 1 12-1 5 5 0 0 1 0 11H6ZM12 9v7m-3-3 3 3 3-3',key:'M14 9a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM13 12l8 8M17 16l3-3',check:'m5 12 4 4L19 6',down:'M12 4v16m-6-6 6 6 6-6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=(v=0)=>`<svg class="art" viewBox="0 0 600 400" role="img" aria-label="模拟风景插画"><rect width="600" height="400" fill="${['#c9d6d7','#d7cfbb','#bdcbd5'][v%3]}"/><circle cx="445" cy="90" r="37" fill="#f1e6c9"/><path d="M0 240 150 100 280 247 430 136 600 275V400H0" fill="${['#718d8d','#9b9e8a','#8298a7'][v%3]}"/><path d="M0 294 185 207 345 283 480 212 600 250V400H0" fill="${['#466e70','#6e806c','#546d80'][v%3]}"/><path d="M0 324q140-35 300-3t300-2v81H0" fill="#abc4c3"/><path d="m230 343 105 0m35 20h87m-300 12h72" stroke="#dce4d9" stroke-width="2" opacity=".65"/></svg>`;
let serial=10;
const initial=[{id:1,text:'周末想去湖边走走，找个安静一点的地方。',time:'16:42'},{id:2,out:true,text:'好啊。上次说的那条小路，应该已经很凉快了。',time:'16:43'},{id:3,type:'image',text:'像这样的天气，就很好。',time:'16:44'},{id:4,text:'不用安排太满，慢慢走就好。',time:'16:45'},{id:5,out:true,text:'那就周六，带上相机和两杯咖啡。',time:'16:46'},{id:6,type:'file',text:'周末的小计划.pdf',time:'16:47'}];
const spaces=[{id:'daily',name:'日常',preview:'周末的小计划.pdf',messages:initial,draft:'',reply:null,scroll:null,unread:0},{id:'travel',name:'一起去远方',preview:'下次，再一起看海。',messages:[{id:7,text:'下次，再一起看海。',time:'昨天 20:12'},{id:8,out:true,text:'把想去的地方慢慢攒起来。',time:'昨天 20:13'}],draft:'',reply:null,scroll:null,unread:2},{id:'waiting',name:'留给下次',preview:'等待对方加入',messages:[],draft:'',waiting:true,unread:0}];
spaces.push({id:'authorization',name:'另一处小天地',pending:true,preview:'需要对方授权',messages:[],draft:'',unread:0});
let active='daily',page='chat',settingsMode=false,tab='相册',online=true,favorites=new Set([3]),lastTrigger=null,restoreTimer=null,flowVisible=false,privacyFocus=null,menuTarget=null;
let sidebarCollapsed=false;
const navButton=()=>`<button class="icon nav-trigger" data-nav aria-label="展开左侧栏" title="展开左侧栏" aria-controls="space-sidebar" aria-expanded="false">${icon('menu')}</button>`;
function syncSidebar(){const wide=$('#frame').clientWidth>=976;$('.sidebar').inert=wide&&sidebarCollapsed;}
function positionTools(){const panel=$('#tools'),trigger=$('#tools-toggle'),zone=$('.composer-zone');if(!panel||panel.hidden||!trigger||!zone)return;const z=zone.getBoundingClientRect(),b=trigger.getBoundingClientRect(),frame=$('#frame').getBoundingClientRect();panel.style.left=Math.max(12,Math.min(b.left-z.left,z.width-panel.offsetWidth-12))+'px';const top=Math.min(b.top,$('#composer').getBoundingClientRect().top);panel.style.bottom=(z.bottom-top+8)+'px';panel.style.maxHeight=Math.max(60,top-frame.top-20)+'px';}
function setSidebarCollapsed(collapsed){const list=$('#timeline');const bottom=list&&list.scrollHeight-list.scrollTop-list.clientHeight<80;const anchor=list&&$$('[data-message]',list).find(e=>e.getBoundingClientRect().bottom>list.getBoundingClientRect().top);const offset=anchor?anchor.getBoundingClientRect().top-list.getBoundingClientRect().top:0;closeMenu();closeNav();sidebarCollapsed=collapsed;$('#workspace').classList.toggle('sidebar-collapsed',collapsed);syncSidebar();positionTools();if(list){if(bottom)list.scrollTop=list.scrollHeight;else if(anchor)list.scrollTop+=anchor.getBoundingClientRect().top-list.getBoundingClientRect().top-offset;current().scroll=list.scrollTop;}if(collapsed)$('[data-nav]')?.focus();else $('#collapse-sidebar').focus();}
const current=()=>spaces.find(s=>s.id===active);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function renderSpaces(){ $('#space-list').innerHTML=`<p class="section-label">${settingsMode?'空间与设置':'只属于彼此'}</p>`+spaces.map(s=>`<button class="space-row ${s.id===active?'active':''}" data-space="${s.id}" ${s.id===active?'aria-current="true"':''}><strong>${esc(s.name)}</strong><time>${s.waiting?'':s.id==='daily'?'16:47':'昨天'}</time><small class="${s.waiting||s.pending?'waiting':''}">${esc(s.waiting?'等待对方加入':s.preview)}</small>${s.unread?`<span class="badge">${s.unread}</span>`:''}</button>`).join('');$('#settings').innerHTML=icon('settings');$('#settings').setAttribute('aria-label','设置');$('#close-nav').innerHTML=icon('close');$('#collapse-sidebar').innerHTML=icon('back');}
function saveChat(){if(page!=='chat')return;const s=current();if($('#message-input'))s.draft=$('#message-input').value;if($('#timeline'))s.scroll=$('#timeline').scrollTop}
function closeNav(){ $('#workspace').classList.remove('nav-open');$('#nav-backdrop').hidden=true;$('.sidebar').removeAttribute('role');$('.sidebar').removeAttribute('aria-modal');$('#content').inert=false; }
function openNav(){ $('#workspace').classList.add('nav-open');$('#nav-backdrop').hidden=false;$('.sidebar').setAttribute('role','dialog');$('.sidebar').setAttribute('aria-modal','true');$('#content').inert=true;$('#close-nav').focus(); }
function go(next){saveChat();page=next;settingsMode=next==='settings';closeMenu();closeNav();render();}
function messageMarkup(m){return `<article class="message ${m.out?'out':''}" data-message="${m.id}"><div class="bubble ${m.type==='image'?'picture':''}">${m.reply?`<div style="font-size:11px;opacity:.75;margin-bottom:8px">回复 · ${esc(m.reply)}</div>`:''}${m.type==='image'?`<button class="media-open" data-view="${m.id}" aria-label="查看图片">${art(m.id)}</button><p class="caption">${esc(m.text)}</p>`:m.type==='file'?`<button class="file-chip" data-read="${m.id}">${icon('file')}<span>${esc(m.text)}<small>PDF · 2 页 · 模拟文件</small></span></button>`:`<p>${esc(m.text)}</p>`}<time>${esc(m.time)}${m.out?' · ✓':''}</time></div><button class="icon message-more" data-more="${m.id}" aria-label="消息操作">${icon('more')}</button></article>`}
function header(title,sub=''){return `<header class="page-header">${navButton()}<button class="icon" data-go="${['settings','favorites','safe'].includes(page)?'chat':'settings'}" aria-label="返回">${icon('back')}</button><h2>${title}</h2><span class="right">${sub||esc(current().name)}</span></header>`}
function renderChat(){const s=current();if(s.pending)return `<header class="chat-header">${navButton()}<div class="header-name">${esc(s.name)}</div></header><div class="empty">${icon('shield')}<h2>再得到一份认可。</h2><p>这台浏览器已由你的设备认可。<br>进入这个空间，还需要对方授权。<br>加入后不会自动获得此前的聊天记录。</p><button class="primary" id="request-access">申请空间授权</button></div>`;return `<header class="chat-header">${navButton()}<div class="header-name-wrap"><div class="header-name">${esc(s.name)}</div><span class="header-subtitle">私密空间</span></div><div class="presence"><span><i></i>对方</span>${icon('heart')}<span class="self-label"><i></i>我</span></div><div class="header-actions"><button class="icon optional" data-go="safe" aria-label="保险箱" title="保险箱">${icon('shield')}</button><button class="icon" id="space-more" aria-label="空间操作">${icon('more')}</button></div></header>${s.waiting?`<div class="empty">${icon('heart')}<h2>给彼此，留一个空间。</h2><p>邀请已经准备好。对方加入后，<br>你们就能在这里开始聊天。</p><button class="primary" id="invite">查看邀请</button></div>`:`<div class="timeline" id="timeline" tabindex="0" aria-label="聊天消息"><div class="day-label">今天 · 9 月 28 日</div>${s.messages.map(messageMarkup).join('')}${!s.messages.length?'<div class="empty"><h2>第一句话，从这里开始。</h2><p>这个空间还没有消息。</p></div>':''}</div><div class="composer-zone"><button id="latest" class="latest" hidden>回到最新 ↓</button><div id="reply-preview" class="reply-preview" ${s.reply?'':'hidden'}><span><small>回复对方</small>${esc(s.reply?.text||'')}</span><button id="cancel-reply" aria-label="取消回复">×</button></div><div class="tools" id="tools" hidden>${[['image','图片'],['camera','拍摄'],['video','视频通话'],['phone','实时语音'],['file','文件'],['star','收藏']].map(([i,t])=>`<button data-tool="${i}">${icon(i)}${t}</button>`).join('')}</div><form id="composer" class="composer"><button class="icon" type="button" id="tools-toggle" aria-label="更多功能" aria-expanded="false">${icon('plus')}</button><div class="input-shell"><textarea id="message-input" aria-label="消息" placeholder="写下一句话…" rows="1">${esc(s.draft)}</textarea><button type="button" class="icon" id="emoji" aria-label="表情">${icon('smile')}</button></div><button class="icon send" type="submit" aria-label="发送消息" ${!s.draft.trim()?'disabled':''}>${icon('send')}</button></form><div class="composer-hint">Enter 发送 · Shift + Enter 换行</div></div>`}`}
const setting=(name,sub,i,action)=>`<button class="setting-row" data-setting="${action}">${icon(i)}<span><strong>${name}</strong><small>${sub}</small></span>${icon('chevron')}</button>`;
function settingsPage(){return header('设置')+`<div class="page-body"><div class="page-intro"><span class="eyebrow">YOUR PRIVATE SPACE</span><h1>把这里，设成喜欢的样子。</h1><p>空间设置仅作用于当前空间，本机设置适用于这台设备。</p></div><section class="settings-group"><h3>当前空间 · ${esc(current().name)}</h3>${setting('空间名称',esc(current().name),'edit','rename')}${setting('在线状态样式','胶囊样式','heart','presence')}${setting('消息备份','下载本机备份、自动云备份','cloud','backup')}${setting('恢复历史记录','从本机文件或云端恢复','file','restore')}</section><section class="settings-group"><h3>本机</h3>${setting('设备管理','查看已授权的设备','device','devices')}${setting('通行密钥','本机名称与管理','key','passkey')}</section><section class="settings-group"><h3>关于</h3>${setting('Quiet Room','有些话，只留给彼此。','heart','about')}</section></div>`}
function galleryPage(){let list=page==='safe'?[3,4,5]:[...favorites];return header(page==='safe'?'保险箱':'收藏',page==='safe'?'创建者可用':'仅保存在本机')+`<div class="page-body"><div class="page-intro"><span class="eyebrow">${page==='safe'?'YOUR SAFE':'SAVED MOMENTS'}</span><h1>${page==='safe'?'想留住的，都在这里。':'把喜欢的，留在手边。'}</h1><p>${page==='safe'?'相册与文件，安静地整理在同一个地方。':'收藏来自当前空间的消息。移除收藏不会删除原消息。'}</p></div><div class="tabs" role="tablist">${['相册','文件'].map(t=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'selected':''}" data-tab="${t}">${t}</button>`).join('')}</div>${tab==='文件'?(page==='safe'||favorites.has(6)?`<button class="setting-row" data-read="6">${icon('file')}<span><strong>周末的小计划.pdf</strong><small>PDF · 模拟阅读</small></span>${icon('chevron')}</button>`:'<div class="empty"><h2>还没有收藏文件</h2><p>在文件消息菜单中选择收藏。</p></div>'):list.length?`<div class="gallery">${list.map((id,i)=>`<button class="gallery-item" data-view="${id}">${art(i)}<div><strong>${['湖边，慢慢走','留给周末','某个晴天'][i%3]}</strong><small>9 月 ${28-i} 日</small></div></button>`).join('')}</div>`:'<div class="empty"><h2>还没有收藏</h2><p>在聊天消息菜单中选择“收藏”，就能在这里找到它。</p></div>'}</div>`}
function taskPage(type){return header(type==='restore'?'恢复历史记录':'消息备份')+`<div class="page-body"><div class="page-intro"><span class="eyebrow">${type==='restore'?'HISTORY':'BACKUP'}</span><h1>${type==='restore'?'让记忆，回到这里。':'给下次见面，留个入口。'}</h1><p>${type==='restore'?'选择恢复来源，再验证属于这个空间的恢复码。':'保存当前设备已有的记录。备份范围取决于本机已有内容。'}</p></div><div class="task-panel">${type==='restore'?`${setting('从本机文件恢复','选择已保存的加密备份','file','restore-file')}${setting('从云端恢复','使用恢复码验证云端记录','cloud','restore-cloud')}`:`${setting('下载本机备份','验证通行密钥后选择保存位置','file','download')}${setting('自动云备份','当前未开启','cloud','cloud-enable')}`}<p style="font-size:11px;color:var(--ink-faint);margin-top:24px">此处演示操作路径，不读取文件、不获取恢复码、不访问云端。</p></div></div>`}
function devicesPage(){return header('设备管理')+`<div class="page-body"><div class="page-intro"><span class="eyebrow">YOUR DEVICES</span><h1>熟悉的设备，安心的连接。</h1><p>每名参与者最多三台独立密钥设备。新设备不自动取得加入前历史。</p></div><section class="settings-group">${setting('这台 Mac','当前设备 · 在线','device','current-device')}${setting('我的 iPhone','已授权 · 上次使用于今天','device','device-info')}</section><button class="secondary" id="new-device">了解新设备接入</button></div>`}
function render(){renderSpaces();$('#content').innerHTML=page==='chat'?renderChat():page==='settings'?settingsPage():['safe','favorites'].includes(page)?galleryPage():page==='devices'?devicesPage():taskPage(page);if(page==='chat'&&!current().waiting&&!current().pending){const list=$('#timeline');list.scrollTop=current().scroll??list.scrollHeight;$('#latest').hidden=list.scrollHeight-list.scrollTop-list.clientHeight<80;list.onscroll=()=>{$('#latest').hidden=list.scrollHeight-list.scrollTop-list.clientHeight<80};const input=$('#message-input');input.oninput=()=>{current().draft=input.value;input.style.height='auto';input.style.height=Math.min(140,input.scrollHeight)+'px';$('.send').disabled=!input.value.trim();positionTools()};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();send()}};$('#composer').onsubmit=e=>{e.preventDefault();send()};}}
function send(){const s=current(),input=$('#message-input');if(!input?.value.trim())return;const text=input.value.trim();s.messages.push({id:++serial,out:true,text,time:'现在',reply:s.reply?.text});s.draft='';s.reply=null;s.preview=text;s.scroll=null;render();$('#message-input').focus();}
function closeMenu(){ $('#menu').hidden=true;menuTarget=null; }
function showMenu(items,x,y){closeMenu();const m=$('#menu');m.innerHTML=items.map(([name,i,action])=>`<button data-menu="${action}">${icon(i)}${name}</button>`).join('');m.hidden=false;m.style.left=Math.min(x,innerWidth-m.offsetWidth-12)+'px';m.style.top=Math.min(y,innerHeight-m.offsetHeight-12)+'px';$('button',m).focus();}
function messageMenu(id,x,y){let m=current().messages.find(m=>m.id===id);if(!m)return;showMenu([['回复','reply','reply'],['复制文字','copy','copy'],...(['image','file'].includes(m.type)?[[favorites.has(id)?'取消收藏':'收藏','star','favorite']]:[])],x,y);menuTarget=m;}
function modal(title,body,buttons=[]){lastTrigger=document.activeElement;const d=$('#modal');d.className='';d.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon" data-close aria-label="关闭">${icon('close')}</button></div>${body}${buttons.length?`<div class="actions">${buttons.map(([label,id,primary])=>`<button id="${id}" class="${primary?'primary':'secondary'}">${label}</button>`).join('')}</div>`:''}`;d.showModal();}
function closeModal(){clearInterval(restoreTimer);restoreTimer=null;$('#modal').close();lastTrigger?.isConnected&&lastTrigger.focus();}
$('#modal').addEventListener('cancel',()=>{clearInterval(restoreTimer);restoreTimer=null});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function rename(){modal('编辑空间名称',`<label for="space-name">空间名称</label><input id="space-name" maxlength="40" value="${esc(current().name)}"><p>仅你可见，不会修改对方的空间名称。</p>`,[['取消','modal-cancel'],['保存','rename-save',true]]);$('#space-name').focus();}
function view(id){modal('湖边，慢慢走',art(id)+`<p>模拟图片 · 原型未加载真实附件</p>`,[[favorites.has(id)?'取消收藏':'收藏','viewer-favorite']]);$('#modal').classList.add('viewer-dialog');$('#viewer-favorite').onclick=()=>{favorites.has(id)?favorites.delete(id):favorites.add(id);$('#viewer-favorite').textContent=favorites.has(id)?'取消收藏':'收藏';toast(favorites.has(id)?'已收藏':'已取消收藏');if(page==='favorites')render()};}
function restore(){modal('验证恢复码',`<p>原型使用演示码，不要输入真实恢复材料。</p><label for="demo-code">演示码</label><input id="demo-code" placeholder="输入 DEMO"><p id="code-error" class="error" hidden>请输入 DEMO 开始演示。</p>`,[['取消','modal-cancel'],['开始恢复','restore-start',true]]);$('#demo-code').focus();}
function startRestore(){if($('#demo-code').value.trim().toUpperCase()!=='DEMO'){$('#code-error').hidden=false;return}$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">正在恢复历史记录</h2><button class="icon" data-close aria-label="关闭并取消恢复">${icon('close')}</button></div><p>模拟验证与导入。关闭将取消未完成的演示。</p><div class="progress-track"><i id="progress"></i></div><p id="progress-label">正在验证来源…</p><div class="actions"><button id="restore-fail" class="secondary">模拟网络失败</button><button data-close>取消恢复</button></div>`;let pct=0;restoreTimer=setInterval(()=>{pct+=20;$('#progress').style.width=pct+'%';$('#progress-label').textContent=pct<100?`正在导入 · ${pct}%`:'恢复完成 · 已核验 24 条模拟记录';if(pct===100){clearInterval(restoreTimer);restoreTimer=null;$('.actions',$('#modal')).innerHTML='<button class="primary" data-close>完成</button>'}},500);$('#restore-fail').onclick=()=>{clearInterval(restoreTimer);restoreTimer=null;$('#progress-label').textContent='连接中断，已完成的导入保留。';$('.actions',$('#modal')).innerHTML='<button data-close>取消恢复</button><button id="retry-restore" class="primary">重试</button>';$('#retry-restore').onclick=()=>{closeModal();restore();$('#demo-code').value='DEMO';startRestore()}};}
function settingAction(a){if(['backup','restore','devices'].includes(a))return go(a);if(a==='rename')return rename();if(a.startsWith('restore-'))return restore();if(a==='download')return modal('下载本机备份','<p>正式产品将在此调用系统通行密钥验证，再进入保存流程。</p><p>演示范围：24 条记录、3 个可用原始附件、0 个缺失附件。</p>',[['返回','modal-cancel']]);if(a==='cloud-enable')return modal('开启自动云备份','<p>开启后，在页面打开、已解锁且联网时备份密文。关闭不会删除已有云端归档。</p><p>原型仅演示这一步说明，不改变实际设置。</p>',[['暂不开启','modal-cancel'],['模拟开启','cloud-confirm',true]]);if(a==='presence')return modal('在线状态样式','<p>沿用现有胶囊与爱心两种样式。此版本展示默认胶囊，状态不代表消息送达或已读。</p>',[['知道了','modal-cancel']]);modal(a==='passkey'?'通行密钥':a==='about'?'Quiet Room':'设备信息','<p>此页面用于核对桌面布局与入口。真实验证、密钥管理与设备撤销沿用现有流程。</p>',[['返回','modal-cancel']]);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b){if(!e.target.closest('#menu'))closeMenu();return}if(!b.closest('#menu')&&!b.dataset.more)closeMenu();if(b.dataset.space){saveChat();active=b.dataset.space;page='chat';settingsMode=false;render();closeNav();return}if(b.dataset.go)return go(b.dataset.go);if(b.id==='collapse-sidebar')return setSidebarCollapsed(true);if(b.hasAttribute('data-nav'))return $('#frame').clientWidth>=976?setSidebarCollapsed(false):openNav();if(b.dataset.setting)return settingAction(b.dataset.setting);if(b.dataset.tab){tab=b.dataset.tab;return render()}if(b.dataset.view)return view(+b.dataset.view);if(b.dataset.read)return modal('周末的小计划.pdf','<div class="page-intro"><span class="eyebrow">模拟文档 · 1 / 2</span><h1>慢一点的周末</h1><p>沿着湖边走走，找一家小店。<br>带相机，不必赶时间。</p></div><p>正式阅读器只在完整校验后本机解析，关闭时清理阅读内容。</p>',[['关闭','modal-cancel']]);if(b.hasAttribute('data-close')||b.id==='modal-cancel')return closeModal();if(b.dataset.more){const r=b.getBoundingClientRect();return messageMenu(+b.dataset.more,r.left,r.bottom)}if(b.dataset.menu){const m=menuTarget;if(b.dataset.menu==='rename'){closeMenu();return rename()}if(!m)return;const action=b.dataset.menu;closeMenu();if(action==='reply'){saveChat();current().reply=m;render();$('#message-input').focus()}if(action==='favorite'){if(!['image','file'].includes(m.type))return toast('只有图片、视频与文件可加入附件收藏');favorites.has(m.id)?favorites.delete(m.id):favorites.add(m.id);toast(favorites.has(m.id)?'已收藏到本机':'已取消收藏')}if(action==='copy'){navigator.clipboard?.writeText(m.text).then(()=>toast('文字已复制')).catch(()=>toast('请直接选择文字复制'))}return}if(b.dataset.tool){$('#tools').hidden=true;$('#tools-toggle').setAttribute('aria-expanded','false');if(b.dataset.tool==='star'){tab='相册';return go('favorites')}if(['phone','video'].includes(b.dataset.tool))return modal(b.dataset.tool==='phone'?'实时语音':'视频通话','<p>通话界面将在正式适配中沿用现有信令、设备授权与媒体权限。本原型不发起真实通话。</p>',[['返回聊天','modal-cancel']]);return modal(b.textContent.trim(),'<p>正式产品在这里打开系统选择器。原型不会申请相机权限或读取本机文件。</p>',[['返回','modal-cancel']]);}
switch(b.id){case'request-access':modal('等待对方授权','<p>请求已模拟发出。正式请求十分钟有效；取消、拒绝或到期均不会取得空间访问权限。</p>',[['取消请求','modal-cancel'],['模拟拒绝','access-reject'],['模拟批准','access-approve',true]]);break;case'access-reject':closeModal();toast('请求被拒绝，尚未获得空间授权');break;case'access-approve':current().pending=false;current().preview='新加入的空间';closeModal();render();break;case'close-nav':case'nav-backdrop':closeNav();break;case'settings':go('settings');break;case'latest':$('#timeline').scrollTop=$('#timeline').scrollHeight;break;case'cancel-reply':saveChat();current().reply=null;render();$('#message-input').focus();break;case'tools-toggle':$('#tools').hidden=!$('#tools').hidden;b.setAttribute('aria-expanded',String(!$('#tools').hidden));positionTools();break;case'emoji':modal('选一个表情','<div style="display:flex;flex-wrap:wrap">'+['🙂','🤍','☕','🌿','🌙','✨'].map(t=>`<button data-emoji="${t}" style="font-size:28px">${t}</button>`).join('')+'</div>');break;case'space-more':{const r=b.getBoundingClientRect();showMenu([['编辑空间名称','edit','rename']],r.left,r.bottom);break}case'rename-save':{const v=$('#space-name').value.trim();if(!v)return toast('请输入空间名称');current().name=v;closeModal();render();toast('空间名称已保存');break}case'create-space':modal('创建新空间','<label for="new-space-name">给这个空间一个名字</label><input id="new-space-name" maxlength="40" placeholder="例如：一起去远方"><p>这将创建一个模拟空间，并展示等待邀请状态。</p>',[['取消','modal-cancel'],['创建','create-confirm',true]]);break;case'create-confirm':{const name=$('#new-space-name').value.trim();if(!name)return toast('请输入空间名称');saveChat();const id='new'+Date.now();spaces.push({id,name,waiting:true,messages:[],draft:'',unread:0});active=id;page='chat';closeModal();closeNav();render();break}case'invite':modal('邀请对方加入','<p>把这个空间留给想说话的人。</p><div style="text-align:center;padding:30px;background:var(--surface);border-radius:16px">演示邀请占位</div><p>原型不生成真实邀请链接或二维码。</p>',[['模拟对方加入','join-demo',true]]);break;case'join-demo':current().waiting=false;current().preview='还没有消息';closeModal();render();break;case'restore-start':startRestore();break;case'cloud-confirm':closeModal();toast('已模拟开启，不影响真实设置');break;case'new-device':modal('新设备接入','<p>新浏览器先由本人已授权设备认可，再按空间取得对方授权。加入后不自动取得旧历史。</p>',[['知道了','modal-cancel']]);break;}
if(b.dataset.emoji){current().draft+=$('[data-emoji="'+b.dataset.emoji+'"]',$('#modal')).textContent;closeModal();render();$('#message-input').focus()}});
document.addEventListener('contextmenu',e=>{const m=e.target.closest('[data-message]');if(m){e.preventDefault();messageMenu(+m.dataset.message,e.clientX,e.clientY)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if($('#workspace').classList.contains('nav-open')){closeNav();$('[data-nav]')?.focus()}if($('#tools'))$('#tools').hidden=true}if(e.key==='Tab'&&$('#workspace').classList.contains('nav-open')){const list=$$('button', $('.sidebar'));if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}});
$('#layout-toggle').onclick=()=>{$('#frame').classList.toggle('narrow');$('#layout-toggle').textContent=$('#frame').classList.contains('narrow')?'桌面窗口':'窄窗口';closeNav()};
$('#theme-toggle').onclick=()=>{document.documentElement.dataset.theme=(document.documentElement.dataset.theme|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))==='dark'?'light':'dark'};
$('#simulate').onclick=()=>{if(current().pending)return toast('尚未获得空间授权，不能接收消息');if(current().waiting)return toast('等待对方加入后才能接收消息');saveChat();const s=current(),list=$('#timeline'),atBottom=list?list.scrollHeight-list.scrollTop-list.clientHeight<80:false;s.messages.push({id:++serial,text:'刚刚看了一下天气，周六是晴天。',time:'现在'});s.preview='刚刚看了一下天气，周六是晴天。';if(page==='chat'){if(atBottom)s.scroll=null;render();if(!atBottom){$('#latest').hidden=false;$('#latest').textContent='1 条新消息 ↓'}}else{renderSpaces();toast('当前空间有一条新消息')}};
$('#privacy-demo').onclick=()=>{privacyFocus=document.activeElement;closeMenu();closeModal();$('#curtain').hidden=false;$('#frame').inert=true;$('.review-bar').inert=true;$('#flow-page').inert=true;$('#resume').focus()};$('#resume').onclick=()=>{$('#curtain').hidden=true;$('#frame').inert=false;$('.review-bar').inert=false;$('#flow-page').inert=false;privacyFocus?.focus()};
const routes=[['01','切换空间',[['选择空间','左栏可收起，顶栏可展开；窄窗口为抽屉'],['检查当前授权','待授权只展示允许的信息'],['进入当前对话','保留各空间草稿与阅读位置']],'侧栏可见不等于消息已读；正式实现继续按前台、焦点与消息可见性判断。'],['02','阅读与发送',[['阅读历史','新消息不打断当前位置'],['回复或输入','右键菜单、Enter 发送'],['回到最新','主动发送或点击新消息提示']],'正在中文输入法组词时，Enter 不发送。窗口变窄不丢失输入内容。'],['03','辅助页面',[['从工具或设置进入','收藏、保险箱、设备与备份'],['在右侧完成任务','主导航保持可达'],['返回原对话','恢复草稿和阅读锚点']],'原型仅展示入口与有限任务交互；媒体和授权仍受原有权限约束。'],['04','历史恢复',[['选择来源','本机文件或云端'],['验证与导入','演示码 DEMO，可模拟失败'],['完成或取消','关闭取消未完成任务']],'真实生命周期中锁定或导航的暂停规则，与用户主动关闭的取消规则分别处理。原型不存储恢复码。'],['05','隐私与返回',[['触发隐私处理','原型使用顶部按钮模拟'],['遮蔽整个工作区','空间列表、聊天与所有弹层'],['按原有规则恢复','演示返回不代表真实认证']],'正式产品必须沿用既有失焦、锁定、双时钟与媒体清理机制，不能以原型遮罩作为安全验证。']];
$('#flow-cards').innerHTML=routes.map(([n,title,steps,note])=>`<section class="flow-route"><h2>${n} · ${title}</h2><div class="flow-steps">${steps.map(([t,d])=>`<div class="flow-step">${t}<small>${d}</small></div>`).join('<b aria-hidden="true">→</b>')}</div><p>${note}</p></section>`).join('');
$('#flows-toggle').onclick=()=>{flowVisible=!flowVisible;$('#frame').hidden=flowVisible;$('#flow-page').hidden=!flowVisible;$('#flows-toggle').textContent=flowVisible?'返回原型':'业务流程'};
new ResizeObserver(()=>{if($('#frame').clientWidth>=976)closeNav();syncSidebar();positionTools()}).observe($('#frame'));
render();
if(location.hash==='#flows')$('#flows-toggle').click();
window.addEventListener('resize',positionTools);
window.addEventListener('hashchange',()=>{if((location.hash==='#flows')!==flowVisible)$('#flows-toggle').click()});
